function* values() {
  try { yield 1; yield 2 }
  finally { console.log("очистка") }
}
for (const value of values()) {
  console.log(value)
  break
}
// Вывод: 1, затем очистка.

function* inner() { yield 1; return 10 }
function* outer() {
  const result = yield* inner()
  yield result + 1
}
console.log([...outer()]) // [1, 11]

function* values() {
  try { yield 1 } finally { yield "cleanup" }
}
const iterator = values()
iterator.next()
console.log(iterator.return("done")) // { value: "cleanup", done: false }
console.log(iterator.next()) // { value: "done", done: true }

const values = Iterator.from([1, 2, 3, 4])
const pipeline = values.filter(value => value % 2 === 0).map(value => value * 10).take(1)
console.log(pipeline.toArray()) // [20]

async function* source() { yield 1; yield 2 }
async function collect() {
  return Array.fromAsync(source(), async value => value * 2)
}
// collect() выполняется в среде с поддержкой Array.fromAsync.

async function* pages(load) {
  for (let page = 1; page <= 3; page++) yield await load(page)
}
// Поддерживаемый load определяет сеть и отмену.
// Очередь iterator.next() не распараллеливает этот цикл.

function* values() {
  try { yield Promise.reject(new Error("сбой")) }
  finally { console.log("очистка") }
}
async function consume() {
  try { for await (const value of values()) console.log(value) }
  catch { console.log("ошибка") }
}
// В текущем описанном алгоритме consume(): очистка, затем ошибка.
// Совместимость конкретного runtime проверяется отдельно.
